    bufferingPolicy: .bufferingNewest(1)
)

let observer = try ditto.store.registerObserver(query: query) {
    @Sendable result in
    let rows = result.items.map { item in
        defer { item.dematerialize() }
        return Row(item.value) // Decode synchronously into your Sendable value type.
    }
    continuation.yield(rows)
}

continuation.onTermination = { [weak observer] _ in
    observer?.cancel()
}

let consumer = Task { @MainActor [weak model] in
    for await rows in updates {
        guard !Task.isCancelled else { break }
        model?.rows = rows
    }
}
