**Tablet (receiver):**

```kotlin
@file:OptIn(com.ditto.kotlin.PreviewDataStreams::class)
import com.ditto.kotlin.*   // includes the open() extension

class SensorReceiver(ditto: Ditto, private val readings: MutableSharedFlow<ByteArray>) : AutoCloseable {
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default)
    private val streams = ConcurrentHashMap<String, DittoStream>()

    private val acceptor = ditto.dataStreams.bindTopic(
        topic = "sensor_data",
        reliability = DittoReliability.Unreliable,
    ) { candidate ->                                   // open inside the callback
        val peer = candidate.peerKeyString()
        val stream = candidate.open { inbound ->
            readings.tryEmit(inbound.payload())        // runs on the driver thread: hand off without blocking, then return
        }
        streams.put(peer, stream)?.let { old -> scope.launch { old.closeSync() } }
        scope.launch { stream.waitUntilClosed(); streams.remove(peer, stream) }
    }

    override fun close() {
        acceptor.close()                               // does NOT close open streams
        val open = streams.values.toList(); streams.clear()
        scope.launch { open.map { launch { it.closeSync() } }.joinAll(); scope.cancel() }
    }
}
```

**Phone (sender):** get the key from presence, then connect from a coroutine you control, once, with retries:

```kotlin
@file:OptIn(com.ditto.kotlin.PreviewDataStreams::class)

suspend fun streamReadings(ditto: Ditto, tabletKey: String, frames: Flow<ByteArray>) {
    var backoff = 500L
    while (currentCoroutineContext().isActive) {
        val stream = try {
            ditto.dataStreams.connect(
                peer = tabletKey,                      // copied out of presence, not called inside it
                topic = "sensor_data",
                reliability = DittoReliability.Unreliable,
                timeoutMs = 10_000,
            ) { candidate -> candidate.open() }        // connect does not open it for you
        } catch (e: CancellationException) { throw e }
        catch (e: DittoException.DataStreamsException) {
            currentCoroutineContext().ensureActive()
            delay(backoff); backoff = minOf(backoff * 2, 10_000); continue   // early HandshakeTimedOut is normal
        }
        backoff = 500
        val max = stream.maxSendSize()
        try {
            frames.collect { f -> if (f.size <= max) stream.sendAndForget(f) }   // reuse one stream
        } finally {
            withContext(NonCancellable) { stream.closeSync() }
        }
        return   // or loop again if the stream dropped; streams never reconnect themselves
    }
}
```

