```kotlin
val readings = Channel<ByteArray>(Channel.CONFLATED)
val incoming = ConcurrentHashMap.newKeySet<DittoStream>()

// Retain this handle for the entire receiving session.
val acceptor = ditto.dataStreams.bindTopic(
    topic = "sensor_data",
    reliability = DittoReliability.Unreliable,
) { candidate ->
    val stream = candidate.open { inbound ->
        readings.trySend(inbound.payload()) // payload() returns an owned copy
    }
    incoming.add(stream)
    sessionScope.launch {
        stream.waitUntilClosed()
        incoming.remove(stream)
    }
}

// Decode and update UI outside the stream's driver-thread callback.
