```kotlin
class SensorReceiver(ditto: Ditto) : AutoCloseable {
    val readings = Channel<ByteArray>(Channel.CONFLATED)

    private val lock = Any()
    private var stopped = false
    private var stream: DittoStream? = null

    private val acceptor = ditto.dataStreams.bindTopic(
        topic = "sensor_data",
        reliability = DittoReliability.Unreliable,
    ) { candidate ->
        // Open while the borrowed candidate is valid.
        val opened = candidate.open { inbound ->
            // payload() returns an owned copy. Never decode or update UI here.
            readings.trySend(inbound.payload())
        }

        synchronized(lock) {
            if (stopped) {
                opened.close()
            } else {
                stream?.close()
                stream = opened
            }
        }
    }

    override fun close() {
        synchronized(lock) {
            stopped = true
            acceptor.close()
            stream?.close() // Closing the acceptor alone does not close streams.
            stream = null
        }
        readings.close()
    }
}
```

