```kotlin
suspend fun sendReadings(
    ditto: Ditto,
    tabletKey: String,
    frames: Flow<ByteArray>,
) = coroutineScope {
    val stream = ditto.dataStreams.connect(
        peer = tabletKey,
        topic = "sensor_data",
        reliability = DittoReliability.Unreliable,
        timeoutMs = 10_000,
    ) { candidate ->
        candidate.open() // connect() does not open it automatically.
    }

    val sender = launch {
        frames.conflate().collect { frame ->
            require(frame.size.toLong() <= stream.maxSendSize())
            stream.sendAndForget(frame)
        }
    }
    val closureWatcher = launch {
        stream.waitUntilClosed()
        sender.cancel()
    }

    try {
        sender.join()
    } finally {
        closureWatcher.cancel()
        sender.cancel()
        withContext(NonCancellable) {
            sender.join()
            stream.closeSync()
        }
    }
}
```

