private fun DittoQueryResult.decodeCars(): List<Car> =
    items.mapNotNull { item ->
        runCatching { carJson.decodeFromString<Car>(item.jsonString()) }
            .onFailure { Log.w("Cars", "Skipping malformed car doc", it) }
            .getOrNull()
    }

// Screen 1
class CarsViewModel(private val ditto: Ditto) : ViewModel() {
    val cars: StateFlow<List<Car>> = ditto.store
        .observe("SELECT * FROM cars") { result ->
            withContext(Dispatchers.IO) { result.decodeCars() }  // decode off Main, inside the transform
        }
        .catch { Log.e("Cars", "Observe failed", it) }          // last-resort guard; Flow does not restart by itself
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), emptyList())
    // no flowOn; viewModelScope cancellation closes the observer
}

// Screen 2
class CarDetailViewModel(private val ditto: Ditto) : ViewModel() {
    private val _cars = MutableStateFlow<List<Car>>(emptyList())   // plain data, never result.items
    val cars: StateFlow<List<Car>> = _cars

    private val observer: DittoStoreObserver =
        ditto.store.registerObserver("SELECT * FROM cars") { result ->
            try {
                _cars.value = withContext(Dispatchers.IO) { result.decodeCars() }
            } catch (t: Throwable) {
                if (t is CancellationException) throw t
                Log.e("CarDetail", "Observer handler failed", t)    // swallow: a throw here closes the observer
            }
