                        readings.collect { frame ->
                            if (frame.size <= max) stream.sendAndForget(frame)  // one stream, every frame
                        }
                    }
                    stream.waitUntilClosed()         // remote closed; reconnect
                    sender.cancel()
                }
            } finally {
                withContext(NonCancellable) { stream.closeSync() }
            }
        } catch (e: CancellationException) { throw e }
        catch (e: DittoException.DataStreamsException) {
            currentCoroutineContext().ensureActive()
            // early Rejected(HandshakeTimedOut) is expected while the tablet is still binding
        }
        delay(backoff); backoff = minOf(backoff * 2, 10_000)
    }
}

