**Tablet:** retain the acceptor and opened streams; copy received bytes into a queue immediately.

```kotlin
class TabletReceiver(ditto: Ditto) : AutoCloseable {
    // Latest reading wins if processing falls behind.
    val readings = Channel<ByteArray>(Channel.CONFLATED)

    private val streams = ConcurrentHashMap.newKeySet<DittoStream>()
    private val acceptor = ditto.dataStreams.bindTopic(
        topic = TOPIC,
        reliability = DittoReliability.Unreliable,
    ) { candidate ->
        streams.add(
            candidate.open { inbound ->
                // Driver thread: payload() produces an owned copy.
                readings.trySend(inbound.payload())
            }
        )
    }

    override fun close() {
        acceptor.close()
        streams.forEach { it.close() }
        streams.clear()
        readings.close()
    }
}
```

