```kotlin
suspend fun sendReadings(
    ditto: Ditto,
    tabletPeerKey: String,       // Selected tablet, not an arbitrary nearby peer
    frames: Flow<ByteArray>,    // Your encoded accelerometer samples
) {
    val peerKey = ditto.presence.observe()
        .mapNotNull { graph ->
            graph.remotePeers
                .firstOrNull { it.peerKey == tabletPeerKey }
                ?.peerKey
        }
        .first()

    val stream = ditto.dataStreams.connect(
        peer = peerKey,
        topic = TOPIC,
        reliability = DittoReliability.Unreliable,
        timeoutMs = 10_000,
    ) { candidate ->
        candidate.open()
    }

    try {
        frames.conflate().collect { frame ->
            require(frame.size.toLong() <= stream.maxSendSize())
            stream.sendAndForget(frame)
        }
    } finally {
        withContext(NonCancellable) { stream.closeSync() }
    }
}
```

