Use this startup pattern in `lib/main.dart`:

```dart
import 'package:ditto_live/ditto_live.dart';
import 'package:flutter/material.dart';

// Retain both handles for the app's lifetime.
late final Ditto ditto;
late final SyncSubscription tasksSubscription;

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();

  const license = String.fromEnvironment('DITTO_OFFLINE_LICENSE');
  const databaseID = String.fromEnvironment('DITTO_DATABASE_ID');
  if (license.isEmpty || databaseID.isEmpty) {
    throw StateError('Supply DITTO_OFFLINE_LICENSE and DITTO_DATABASE_ID');
  }

  await Ditto.init();
  ditto = await Ditto.open(
    const DittoConfig(
      databaseID: databaseID,
      connect: DittoConfigConnectSmallPeersOnly(),
    ),
  );

  late final List<String> titles;
  try {
    ditto.setOfflineOnlyLicenseToken(license);

    // LAN-only starter; small-peers-only means no Ditto server.
    ditto.updateTransportConfig((config) {
      config.peerToPeer.lan.isEnabled = true;
      config.peerToPeer.bluetoothLE.isEnabled = false;
      config.peerToPeer.awdl.isEnabled = false;
      config.peerToPeer.wifiAware.isEnabled = false;
    });

    ditto.sync.start();
    tasksSubscription =
        ditto.sync.registerSubscription('SELECT * FROM tasks');

    await ditto.store.execute(
      'INSERT INTO tasks DOCUMENTS (:task) ON ID CONFLICT DO UPDATE',
      arguments: {
        'task': {
          '_id': 'task-1',
          'title': 'Try Ditto',
        },
      },
    );

    final result = await ditto.store.execute('SELECT title FROM tasks');
    titles = result.items
        .map((item) => item.value['title'] as String)
        .toList();
  } catch (_) {
    await ditto.close();
    rethrow;
  }

  runApp(MaterialApp(
    home: Scaffold(
      body: SafeArea(
        child: ListView(
          children: titles.map((title) => ListTile(title: Text(title))).toList(),
        ),
      ),
    ),
  ));
}
```

