Presence shows connected mesh peers; it does not scan every nearby device or provide distance.

```dart
import 'package:ditto_live/ditto_live.dart';
import 'package:flutter/material.dart';

class NearbyPeersScreen extends StatefulWidget {
  const NearbyPeersScreen({super.key, required this.ditto});

  final Ditto ditto;

  @override
  State<NearbyPeersScreen> createState() => _NearbyPeersScreenState();
}

class _NearbyPeersScreenState extends State<NearbyPeersScreen> {
  PresenceObserver? _observer;
  List<Peer> _peers = [];
  String _localPeerKey = '';

  @override
  void initState() {
    super.initState();
    // Delivers the current graph, then peer/connection changes.
    _observer = widget.ditto.presence.observe((graph) {
      if (!mounted) return;

      final peers = graph.remotePeers.toList()
        ..sort((a, b) {
          final byName = a.deviceName.compareTo(b.deviceName);
          return byName != 0 ? byName : a.peerKey.compareTo(b.peerKey);
        });

      setState(() {
        _localPeerKey = graph.localPeer.peerKey;
        _peers = peers;
      });
    });
  }

  static String _transportLabel(ConnectionType type) => switch (type) {
        ConnectionType.bluetooth => 'Bluetooth',
        ConnectionType.accessPoint => 'LAN',
        ConnectionType.p2pWifi => 'Wi-Fi P2P',
        ConnectionType.webSocket => 'WebSocket',
        ConnectionType.multicast => 'Multicast',
      };

  String _connectionLabel(Peer peer) {
    // Only label links directly between this device and this peer.
    final labels = peer.connections
        .where((c) =>
            (c.peer1 == _localPeerKey && c.peer2 == peer.peerKey) ||
            (c.peer2 == _localPeerKey && c.peer1 == peer.peerKey))
        .map((c) => _transportLabel(c.connectionType))
        .toSet()
        .toList()
      ..sort();

    return labels.isEmpty
        ? 'Via mesh (no direct connection)'
        : labels.join(', ');
  }

  @override
  void dispose() {
    _observer?.stop();
    // The app owns Ditto; keep it open.
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Nearby peers')),
      body: _peers.isEmpty
          ? const Center(child: Text('No connected peers'))
          : ListView.builder(
              itemCount: _peers.length,
              itemBuilder: (context, index) {
                final peer = _peers[index];
                return ListTile(
                  key: ValueKey(peer.peerKey),
                  leading: const Icon(Icons.devices),
                  title: Text(
                    peer.deviceName.trim().isEmpty
                        ? 'Unnamed device'
                        : peer.deviceName,
                  ),
                  subtitle: Text(_connectionLabel(peer)),
                );
              },
            ),
    );
  }
}
```

