This uses one `changes` listener, binds the color as a query argument, and cancels both handles on disposal. It also handles changes to the widget’s color or Ditto instance.

```dart
import 'dart:async';

import 'package:ditto_live/ditto_live.dart';
import 'package:flutter/material.dart';

class CarsScreen extends StatefulWidget {
  const CarsScreen({
    super.key,
    required this.ditto,
    required this.color,
  });

  final Ditto ditto;
  final String color;

  @override
  State<CarsScreen> createState() => _CarsScreenState();
}

class _CarsScreenState extends State<CarsScreen> {
  late StoreObserver _observer;
  late StreamSubscription<QueryResult> _changes;
  List<Map<String, dynamic>> _cars = [];
  int _generation = 0;

  @override
  void initState() {
    super.initState();
    _startWatching();
  }

  void _startWatching() {
    final generation = ++_generation;

    // Listen immediately; don't also supply onChange.
    _observer = widget.ditto.store.registerObserver(
      'SELECT * FROM cars WHERE color = :color',
      arguments: {'color': widget.color},
    );
    _changes = _observer.changes.listen((result) {
      if (!mounted || generation != _generation) return;

      final cars = result.items.map((item) => item.value).toList();
      setState(() => _cars = cars);
    });
  }

  void _stopWatching() {
    ++_generation; // Ignore any stale callbacks.
    unawaited(_changes.cancel());
    _observer.cancel();
  }

  @override
  void didUpdateWidget(covariant CarsScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.color != widget.color ||
        !identical(oldWidget.ditto, widget.ditto)) {
      _stopWatching();
      _cars = [];
      _startWatching();
    }
  }

  @override
  void dispose() {
    _stopWatching();
    // The app owns Ditto; don't close it here.
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('${widget.color} cars')),
      body: _cars.isEmpty
          ? const Center(child: Text('No matching cars'))
          : ListView.builder(
              itemCount: _cars.length,
              itemBuilder: (context, index) {
                final car = _cars[index];
                return ListTile(
                  title: Text('${car['make'] ?? car['_id']}'),
                  subtitle: Text('${car['color']}'),
                );
              },
            ),
    );
  }
}
```

The observer watches the local store. For cars arriving from peers or cloud, the app also needs an active sync subscription covering those cars. Keep the shared Ditto instance open during screen cleanup.

For 5.2.0:

- Replace the identity with `DittoConfig`: `appId` becomes `databaseID`; copy the server URL verbatim from the portal.
- Install and await an auth expiration handler before starting sync. Playground login uses `Authenticator.developmentProvider`.
- Replace `startSync()` with `sync.start()`.
- Remove `ORDER BY` and `LIMIT` from the sync subscription; apply them to local queries.
- Rename `isConnectedToDittoCloud` to `isConnectedToDittoServer`. `remotePeers` is now a `Set`; `.any()` still works.
- `Ditto.init()` is optional before async `open()` in 5.2.0, but keeping it is valid.

```dart
import 'dart:developer' as developer;
import 'package:ditto_live/ditto_live.dart';

await Ditto.init();

final ditto = await Ditto.open(DittoConfig(
  databaseID: appId,
  connect: DittoConfigConnectServer(url: serverUrl),
));

await ditto.auth.setExpirationHandler((ditto, _) async {
  if (ditto.isClosed) return;
  try {
    final response = await ditto.auth.login(
      token: playgroundToken,
      provider: Authenticator.developmentProvider,
    );
    if (response.exception != null) {
      developer.log('Ditto login failed: ${response.exception}');
    }
  } catch (error) {
    developer.log('Ditto login threw: $error');
  }
});

final subscription =
    ditto.sync.registerSubscription('SELECT * FROM orders');

ditto.sync.start();

// Query the currently available local documents.
final orders = await ditto.store.execute(
  'SELECT * FROM orders ORDER BY createdAt LIMIT 50',
);

// Snapshot: whether any remote peer reports a server connection.
final online = ditto.presence.graph.remotePeers
    .any((p) => p.isConnectedToDittoServer);
```

