```dart
import 'package:ditto_live/ditto_live.dart';
import 'package:flutter/material.dart';

class CarsByColorScreen extends StatefulWidget {
  const CarsByColorScreen({super.key, required this.ditto, required this.color});

  final Ditto ditto;
  final String color;

  @override
  State<CarsByColorScreen> createState() => _CarsByColorScreenState();
}

class _CarsByColorScreenState extends State<CarsByColorScreen> {
  static const _query = 'SELECT * FROM cars WHERE color = :color';

  SyncSubscription? _subscription; // pulls matching docs from peers
  StoreObserver? _observer;        // fires on local changes
  List<Map<String, dynamic>> _cars = const [];

  @override
  void initState() {
    super.initState();
    _start(widget.color);
  }

  @override
  void didUpdateWidget(CarsByColorScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    // Re-register if the parent passes a new color or Ditto instance.
    if (oldWidget.color != widget.color || oldWidget.ditto != widget.ditto) {
      _stop();
      _start(widget.color);
    }
  }

  void _start(String color) {
    final args = {'color': color};

    _subscription = widget.ditto.sync.registerSubscription(_query, arguments: args);

    _observer = widget.ditto.store.registerObserver(
      _query,
      arguments: args,
      onChange: (QueryResult result) {
        final cars = result.items.map((item) => item.value).toList();
        if (!mounted) return; // a callback may arrive after dispose
        setState(() => _cars = cars);
      },
    );
  }

  void _stop() {
    _observer?.cancel();
    _observer = null;
    _subscription?.cancel();
    _subscription = null;
  }

  @override
  void dispose() {
    _stop();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('${widget.color} cars')),
      body: _cars.isEmpty
          ? const Center(child: Text('No cars'))
          : ListView.builder(
              itemCount: _cars.length,
              itemBuilder: (context, i) {
                final car = _cars[i];
                return ListTile(
                  key: ValueKey(car['_id']),
                  title: Text('${car['make'] ?? ''} ${car['model'] ?? ''}'.trim()),
                  subtitle: Text('${car['color']}'),
                );
              },
            ),
    );
  }
}
```

Usage: `CarsByColorScreen(ditto: ditto, color: 'blue')`

How it works:
- **Live updates:** `registerObserver` runs `onChange` with the current results right away, then again whenever a matching document is added, changed or removed in the local store.
- **Sync from other devices:** the observer only watches local data. `registerSubscription` with the same query is what pulls matching documents from other devices. This assumes the app already calls `ditto.startSync()` at startup.
- **Safe query:** the color is passed as the `:color` argument, not pasted into the query string.
- **Cleanup:** `dispose()` cancels both the observer and the subscription, so nothing leaks and `setState` is never called after the screen closes. The `mounted` check covers a callback that is already on its way when the screen closes.
- **Color changes:** if the parent passes a new `color` while the screen is open, `didUpdateWidget` cancels the old observer and subscription and registers new ones.

If your app uses a different field than `make`/`model` for display, change the `ListTile` text.

Use a store observer for live local results and a sync subscription to request matching cars from peers. This also handles changes to the widget’s color or Ditto instance.

```dart
import 'package:ditto_live/ditto_live.dart';
import 'package:flutter/material.dart';

class CarsScreen extends StatefulWidget {
  const CarsScreen({
    super.key,
    required this.ditto,
    required this.color,
  });

  final Ditto ditto;
  final String color;

  @override
  State<CarsScreen> createState() => _CarsScreenState();
}

class _CarsScreenState extends State<CarsScreen> {
  static const _query = 'SELECT * FROM cars WHERE color = :color';

  List<Map<String, dynamic>> _cars = [];
  VoidCallback? _cancelObserver;
  VoidCallback? _cancelSubscription;
  int _generation = 0;
  bool _loading = true;

  @override
  void initState() {
    super.initState();
    _observe();
  }

  @override
  void didUpdateWidget(covariant CarsScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (!identical(oldWidget.ditto, widget.ditto) ||
        oldWidget.color != widget.color) {
      _stop();
      _cars = [];
      _loading = true;
      _observe();
    }
  }

  void _observe() {
    final generation = ++_generation;
    final arguments = <String, dynamic>{'color': widget.color};

    final subscription = widget.ditto.sync.registerSubscription(
      _query,
      arguments: arguments,
    );
    _cancelSubscription = () => subscription.cancel();

    final observer = widget.ditto.store.registerObserver(
      _query,
      arguments: arguments,
      onChange: (result) {
        if (!mounted || generation != _generation) return;

        final cars = result.items
            .map((item) => Map<String, dynamic>.from(item.value))
            .toList();

        setState(() {
          _cars = cars;
          _loading = false;
        });
      },
    );
    _cancelObserver = () => observer.cancel();
  }

  void _stop() {
    ++_generation; // Ignore callbacks queued by an older observer.
    _cancelObserver?.call();
    _cancelObserver = null;
    _cancelSubscription?.call();
    _cancelSubscription = null;
  }

  @override
  void dispose() {
    _stop();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('${widget.color} cars')),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : _cars.isEmpty
              ? const Center(child: Text('No matching cars'))
              : ListView.builder(
                  itemCount: _cars.length,
                  itemBuilder: (context, index) {
                    final car = _cars[index];
                    return ListTile(
                      title: Text(
                        car['name']?.toString() ??
                            car['_id']?.toString() ??
                            'Car',
                      ),
                      subtitle: Text(car['color']?.toString() ?? ''),
                    );
                  },
                ),
    );
  }
}
```

The observer supplies the initial results and subsequent changes. Only screen-owned observers and subscriptions are canceled; the shared `Ditto` instance stays open. No files changed or tests run.

You don't need to add any Bluetooth permissions to `android/`. The `ditto_live` plugin already declares them in its own `AndroidManifest.xml`. Gradle merges that file into your app's debug and release builds. (I also didn't find an `android/` folder in this workspace, so I haven't edited anything.)

**What the plugin already declares (ditto_live 5.2.0):**
- `BLUETOOTH_SCAN` (with `neverForLocation`), `BLUETOOTH_CONNECT` and `BLUETOOTH_ADVERTISE`
- `BLUETOOTH` and `BLUETOOTH_ADMIN`, up to API 30
- `ACCESS_FINE_LOCATION` up to API 32, and `ACCESS_COARSE_LOCATION` up to API 30
- `NEARBY_WIFI_DEVICES` (with `neverForLocation`) and `INTERNET`

Don't declare these again in `android/app/src/main/AndroidManifest.xml` with different `maxSdkVersion` or `usesPermissionFlags` values, because that can conflict with the plugin's entries. If you do edit the manifest, check the merged manifest afterwards. The only optional line is this one, which just makes the requirement visible in your app:

```xml
<uses-permission android:name="android.permission.INTERNET" />
```

**What you do need to do:** ask the user for the permissions at runtime, before `ditto.sync.start()`. Ditto never requests them itself. On 5.1.0 and later, `DittoSyncPermissions` tells you which ones are missing, and you request them with `permission_handler`:

```dart
import 'package:ditto_live/ditto_live.dart';
import 'package:permission_handler/permission_handler.dart';

const _runtimePermissions = <String, Permission>{
  'android.permission.BLUETOOTH_SCAN': Permission.bluetoothScan,
  'android.permission.BLUETOOTH_CONNECT': Permission.bluetoothConnect,
  'android.permission.BLUETOOTH_ADVERTISE': Permission.bluetoothAdvertise,
  'android.permission.NEARBY_WIFI_DEVICES': Permission.nearbyWifiDevices,
  'android.permission.ACCESS_FINE_LOCATION': Permission.locationWhenInUse,
  'android.permission.ACCESS_COARSE_LOCATION': Permission.locationWhenInUse,
  'android.permission.POST_NOTIFICATIONS': Permission.notification,
};

Future<List<String>> requestDittoPermissions() async {
  final permissions = DittoSyncPermissions();
  final missing = await permissions.missingPermissions();
  final requests = missing.map((n) => _runtimePermissions[n]).nonNulls;
  if (requests.isNotEmpty) await requests.toSet().toList().request();
  return permissions.missingPermissions(); // still missing
}

// await requestDittoPermissions();
// ditto.sync.start();
```

- **On 5.0.x:** `DittoSyncPermissions` doesn't exist, so request the Bluetooth, nearby-devices and location permissions directly with `permission_handler`.
- **If permission is granted after sync has started:** it only takes effect after you call `ditto.sync.stop()` and then `ditto.sync.start()`.

There are four bugs here, three of them about lifetimes.

1. **`ditto.close()` in `dispose()` breaks every other screen.** You should have one `Ditto` per process. Open it before `runApp` and close it only when the app exits. This screen closes the shared instance, so every screen after it is using a closed Ditto. Re-opening it in the same process can also abort or hang the app.
2. **`onChange` makes memory grow.** On 5.0.x–5.2.0, an observer registered with `onChange` also keeps every result in its `changes` stream. Nothing listens to that stream, so it grows without limit while the screen is open. The fix is to drop `onChange` and attach one `changes` listener right away.
3. **Nothing gets cancelled.** Losing the reference to an observer or subscription doesn't stop it. Both keep running after the screen is gone, and `setState` would then be called on an unmounted widget. Cancel the listener, then the observer, then the subscription, all while Ditto is still open.
4. **The subscription query is rejected.** `registerSubscription` throws on `LIMIT` or `ORDER BY`. The subscription only says which documents to sync, so sort and limit in the observer query instead.

Also, `result.items` is a lazy `Iterable`, so copy it into a list before calling `setState`.

```dart
import 'dart:async';

class _InventoryState extends State<InventoryScreen> {
  List<Map<String, dynamic>> _items = [];
  late final SyncSubscription _subscription;
  late final StoreObserver _observer;
  late final StreamSubscription<QueryResult> _changes;

  @override
  void initState() {
    super.initState();
    // Which documents to sync: no LIMIT / ORDER BY here.
    _subscription = widget.ditto.sync.registerSubscription('SELECT * FROM items');
    // No onChange: listen to `changes` once, right away.
    _observer = widget.ditto.store.registerObserver(
        'SELECT * FROM items ORDER BY name LIMIT 100');
    _changes = _observer.changes.listen((result) {
      if (!mounted) return;
      final items = result.items.map((i) => i.value).toList(); // copy
      setState(() => _items = items);
    });
  }

  @override
  void dispose() {
    unawaited(_changes.cancel()); // listener first
    _observer.cancel();           // then the observer
    _subscription.cancel();       // then the subscription
    // Do NOT close Ditto here; the app-level service owns it.
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Text('${_items.length} items');
}
```

`widget.ditto` should come from an app-level service that opens Ditto once at startup and closes it only on exit. For larger apps, it's better to put the observer in a repository that exposes a `ValueNotifier`. Don't use a `StreamBuilder` over `changes`: a rebuild throws "Stream has already been listened to", and the observer outlives it.

