Here's the screen. It's based on the `ditto_live` 5.2.0 presence API as documented in the local Flutter SDK guidance (`references/presence.md`). As you asked, I didn't change any files or run anything.

```dart
// lib/screens/nearby_peers_screen.dart
import 'package:ditto_live/ditto_live.dart';
import 'package:flutter/material.dart';

/// Lists remote peers, live. Pass in the app-wide [Ditto] (opened once,
/// before runApp, by your service) — this screen never opens or closes it.
class NearbyPeersScreen extends StatefulWidget {
  const NearbyPeersScreen({super.key, required this.ditto});

  final Ditto ditto;

  @override
  State<NearbyPeersScreen> createState() => _NearbyPeersScreenState();
}

class _PeerRow {
  const _PeerRow(this.peerKey, this.deviceName, this.os, this.transports);
  final String peerKey;
  final String deviceName;
  final String os;
  /// Empty = reachable only via another peer (multihop).
  final List<String> transports;
}

class _NearbyPeersScreenState extends State<NearbyPeersScreen> {
  PresenceObserver? _observer;
  List<_PeerRow> _peers = const [];

  @override
  void initState() {
    super.initState();
    // Fires once shortly after registering with the current graph, then on
    // every peer/connection change, on this (UI) isolate.
    _observer = widget.ditto.presence.observe(_onGraph);
  }

  void _onGraph(PresenceGraph graph) {
    final localKey = graph.localPeer.peerKey;
    // Copy into plain values; don't keep SDK objects in state.
    final rows = graph.remotePeers.map((peer) {
      final direct = peer.connections
          .where((c) => c.peer1 == localKey || c.peer2 == localKey)
          .map((c) => _label(c.connectionType))
          .toSet()
          .toList()
        ..sort();
      return _PeerRow(peer.peerKey, peer.deviceName, '${peer.os}', direct);
    }).toList()
      ..sort((a, b) => a.deviceName.compareTo(b.deviceName));

    if (!mounted) return;
    setState(() => _peers = rows);
  }

  static String _label(ConnectionType type) => switch (type) {
        ConnectionType.bluetooth => 'Bluetooth',
        ConnectionType.accessPoint => 'LAN',
        ConnectionType.p2pWifi => 'Wi-Fi P2P',
        ConnectionType.webSocket => 'WebSocket',
        ConnectionType.multicast => 'Multicast', // 5.1.0+
      };

  @override
  void dispose() {
    // Dropping the observer does NOT stop it — stop() explicitly.
    _observer?.stop();
    _observer = null;
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Nearby peers (${_peers.length})')),
      body: _peers.isEmpty
          ? const Center(child: Text('No peers found yet'))
          : ListView.separated(
              itemCount: _peers.length,
              separatorBuilder: (_, __) => const Divider(height: 1),
              itemBuilder: (context, i) {
                final p = _peers[i];
                return ListTile(
                  key: ValueKey(p.peerKey),
                  leading: Icon(p.transports.isEmpty
                      ? Icons.device_hub
                      : Icons.devices),
                  title: Text(p.deviceName.isEmpty ? p.peerKey : p.deviceName),
                  subtitle: Text(p.os),
                  trailing: Wrap(
                    spacing: 4,
                    children: p.transports.isEmpty
                        ? const [Chip(label: Text('via mesh'))]
                        : [for (final t in p.transports) Chip(label: Text(t))],
                  ),
                );
              },
            ),
    );
  }
}
```

Open it with `Navigator.push(context, MaterialPageRoute(builder: (_) => NearbyPeersScreen(ditto: ditto)))`.

- **Watching and stopping:** `ditto.presence.observe(...)` gives you a `PresenceObserver`. To stop it you call `stop()`, not `cancel()`. Discarding the observer doesn't stop it, because Ditto keeps the callback until `stop()` or `close()`. That's why `dispose()` calls `stop()`.
- **How each peer is connected:** each peer's `connections` can include links to other peers too. The screen only shows connections where `peer1` or `peer2` is your own device's peer key. A peer with no such link is reached through other devices and is labelled "via mesh".
- **Version:** the `multicast` case only exists from 5.1.0, so this `switch` compiles on 5.2.0 but not on 5.0.x.
- **Don't close Ditto here:** never call `ditto.close()` in `dispose()`. Close it only when the app exits.
- **Platform setup:** peers only appear if Bluetooth and LAN are allowed. That means runtime permissions on Android, Info.plist keys on iOS, and the network entitlements in both macOS `.entitlements` files (`DebugProfile` and `Release`). Flutter Web has no peer-to-peer, so this list would always be empty there.
- **Hot restart:** presence callbacks use the same mechanism that crashed other observer types after a hot restart (`R`). This hasn't been tested for presence, so do a full restart while working on this screen.

