Register it inside **`DisposableEffect`**, and close the returned handle in `onDispose`. This ties it to the screen’s composition lifetime:

```kotlin
@Composable
fun CarsScreen(ditto: Ditto) {
    var rows by remember { mutableStateOf(emptyList<String>()) }
    val query = "SELECT * FROM cars"

    DisposableEffect(ditto, query) {
        val observer = ditto.store.registerObserver(query) { result ->
            rows = result.items.map { it.jsonString() }
        }

        onDispose {
            observer.close()
        }
    }

    // Render rows.
}
```

Recomposition keeps the existing observer; leaving composition closes it. Changed effect keys close and recreate it.

Extract plain data inside the callback—Ditto closes results and items when it returns. Keep the `Ditto` instance in an application singleton.

Pass your existing, open `Ditto` instance with sync running and native permissions granted. Presence shows peers known to the mesh; it does not measure physical proximity. This screen labels direct connections and marks other peers as indirect.

```dart
import 'package:ditto_live/ditto_live.dart';
import 'package:flutter/material.dart';

class NearbyPeersScreen extends StatefulWidget {
  const NearbyPeersScreen({super.key, required this.ditto});

  final Ditto ditto;

  @override
  State<NearbyPeersScreen> createState() => _NearbyPeersScreenState();
}

class _NearbyPeersScreenState extends State<NearbyPeersScreen> {
  PresenceObserver? _observer;
  List<Peer> _peers = [];
  String _localPeerKey = '';

  @override
  void initState() {
    super.initState();
    _watch();
  }

  void _watch() {
    // observe delivers the current graph, then subsequent changes.
    _observer = widget.ditto.presence.observe((graph) {
      if (!mounted) return;

      final peers = graph.remotePeers.toList()
        ..sort((a, b) {
          final result = a.deviceName.compareTo(b.deviceName);
          return result != 0 ? result : a.peerKey.compareTo(b.peerKey);
        });

      setState(() {
        _localPeerKey = graph.localPeer.peerKey;
        _peers = peers;
      });
    });
  }

  @override
  void didUpdateWidget(covariant NearbyPeersScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (!identical(oldWidget.ditto, widget.ditto)) {
      _observer?.stop();
      _peers = [];
      _localPeerKey = '';
      _watch();
    }
  }

  String _connectionLabel(Peer peer) {
    final labels = peer.connections
        .where((connection) =>
            (connection.peer1 == _localPeerKey &&
                connection.peer2 == peer.peerKey) ||
            (connection.peer2 == _localPeerKey &&
                connection.peer1 == peer.peerKey))
        .map((connection) => switch (connection.connectionType) {
              ConnectionType.bluetooth => 'Bluetooth',
              ConnectionType.accessPoint => 'LAN',
              ConnectionType.p2pWifi => 'Wi-Fi P2P',
              ConnectionType.webSocket => 'WebSocket',
              ConnectionType.multicast => 'Multicast',
            })
        .toSet()
        .toList()
      ..sort();

    return labels.isEmpty ? 'Indirect (via mesh)' : labels.join(', ');
  }

  @override
  void dispose() {
    _observer?.stop();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Nearby peers')),
      body: _peers.isEmpty
          ? const Center(child: Text('No peers connected'))
          : ListView.builder(
              itemCount: _peers.length,
              itemBuilder: (context, index) {
                final peer = _peers[index];
                return ListTile(
                  key: ValueKey(peer.peerKey),
                  leading: const Icon(Icons.devices),
                  title: Text(
                    peer.deviceName.isEmpty
                        ? 'Unnamed device'
                        : peer.deviceName,
                  ),
                  subtitle: Text(_connectionLabel(peer)),
                );
              },
            ),
    );
  }
}
```

`PresenceObserver.stop()` ends watching when the screen is disposed; the shared Ditto instance stays open.

