This example follows the installed guidance for Ditto **5.1/5.2**. Use Flutter 3.24.5+.

Before running:

- **iOS:** use CocoaPods, set the deployment target and `ios/Podfile` platform to iOS 15.
- **Android:** set `minSdk = 24`. Ditto 5.1/5.2 needs `compileSdk = 36` in the plugin module as well as your app; the local [setup guidance](.agents/skills/flutter-sdk/references/setup.md) provides the Gradle override.

Add these entries inside the dictionary in `ios/Runner/Info.plist`:

```xml
<key>NSBluetoothAlwaysUsageDescription</key>
<string>Sync tasks with nearby devices over Bluetooth.</string>
<key>NSLocalNetworkUsageDescription</key>
<string>Sync tasks with nearby devices on the local network.</string>
<key>NSBonjourServices</key>
<array>
    <string>_http-alt._tcp.</string>
</array>
```

The Ditto plugin declares Android’s transport permissions. Your app must request runtime access.

Use this as `lib/main.dart`, replacing the database ID and supplying your offline license:

```dart
import 'package:ditto_live/ditto_live.dart';
import 'package:flutter/material.dart';
import 'package:permission_handler/permission_handler.dart';

// Retain these for the app's lifetime.
late final Ditto ditto;
late final SyncSubscription tasksSubscription;

const runtimePermissions = <String, Permission>{
  'android.permission.BLUETOOTH_SCAN': Permission.bluetoothScan,
  'android.permission.BLUETOOTH_CONNECT': Permission.bluetoothConnect,
  'android.permission.BLUETOOTH_ADVERTISE': Permission.bluetoothAdvertise,
  'android.permission.NEARBY_WIFI_DEVICES': Permission.nearbyWifiDevices,
  'android.permission.ACCESS_FINE_LOCATION': Permission.locationWhenInUse,
  'android.permission.ACCESS_COARSE_LOCATION': Permission.locationWhenInUse,
  'android.permission.POST_NOTIFICATIONS': Permission.notification,
};

Future<void> requestSyncPermissions() async {
  // These lists are empty on iOS.
  final permissions = DittoSyncPermissions();
  final missing = await permissions.missingPermissions();
  final requests = missing
      .map((name) => runtimePermissions[name])
      .whereType<Permission>()
      .toSet()
      .toList();

  if (requests.isNotEmpty) await requests.request();

  final remaining = await permissions.missingPermissions();
  if (remaining.isNotEmpty) {
    throw StateError('Sync permissions denied: $remaining');
  }
}

Future<List<String>> taskTitles(Ditto ditto) async {
  final result = await ditto.store.execute('SELECT title FROM tasks');

  // items is an Iterable; materialize the titles as List<String>.
  return result.items
      .map((item) => item.value['title'] as String)
      .toList();
}

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();

  const license = String.fromEnvironment('DITTO_OFFLINE_LICENSE');
  if (license.isEmpty) {
    throw StateError('Supply DITTO_OFFLINE_LICENSE');
  }

  await Ditto.init();
  ditto = await Ditto.open(
    const DittoConfig(
      databaseID: 'REPLACE_WITH_YOUR_DATABASE_ID',
      connect: DittoConfigConnectSmallPeersOnly(),
    ),
  );

  SyncSubscription? subscription;
  late final List<String> titles;
  try {
    ditto.setOfflineOnlyLicenseToken(license);
    await requestSyncPermissions();

    // Native peer-to-peer transports are enabled by default.
    ditto.sync.start();
    subscription =
        ditto.sync.registerSubscription('SELECT * FROM tasks');

    await ditto.store.execute(
      'INSERT INTO tasks DOCUMENTS (:task) ON ID CONFLICT DO UPDATE',
      arguments: {
        'task': {
          '_id': 'first-task',
          'title': 'Try Ditto',
          'done': false,
        },
      },
    );

    titles = await taskTitles(ditto); // ['Try Ditto'] on a fresh store
    tasksSubscription = subscription;
  } catch (_) {
    subscription?.cancel();
    await ditto.close();
    rethrow;
  }

  runApp(MaterialApp(
    home: Scaffold(
      appBar: AppBar(title: const Text('Tasks')),
      body: ListView(
        children: [
          for (final title in titles) ListTile(title: Text(title)),
        ],
