This uses one `changes` listener, copies results into widget state, and cancels both the listener and observer. It also updates the query if the supplied color or Ditto instance changes.

```dart
import 'dart:async';

import 'package:ditto_live/ditto_live.dart';
import 'package:flutter/material.dart';

class CarsScreen extends StatefulWidget {
  const CarsScreen({
    super.key,
    required this.ditto,
    required this.color,
  });

  final Ditto ditto;
  final String color;

  @override
  State<CarsScreen> createState() => _CarsScreenState();
}

class _CarsScreenState extends State<CarsScreen> {
  late StoreObserver _observer;
  late StreamSubscription<QueryResult> _changes;
  List<Map<String, dynamic>> _cars = [];
  int _generation = 0;

  @override
  void initState() {
    super.initState();
    _observe();
  }

  void _observe() {
    final generation = ++_generation;
    _observer = widget.ditto.store.registerObserver(
      'SELECT * FROM cars WHERE color = :color',
      arguments: {'color': widget.color},
    );

    // Listen immediately, once; do not also supply onChange.
    _changes = _observer.changes.listen((result) {
      if (!mounted || generation != _generation) return;

      final cars = result.items.map((item) => item.value).toList();
      setState(() => _cars = cars);
    });
  }

  void _stopObserving() {
    ++_generation; // Ignore any stale callbacks.
    unawaited(_changes.cancel());
    _observer.cancel();
  }

  @override
  void didUpdateWidget(covariant CarsScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (!identical(oldWidget.ditto, widget.ditto) ||
        oldWidget.color != widget.color) {
      _stopObserving();
      _cars = [];
      _observe();
    }
  }

  @override
  void dispose() {
    _stopObserving();
    // The app owns Ditto; leave it open.
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('${widget.color} cars')),
      body: _cars.isEmpty
          ? const Center(child: Text('No matching cars'))
          : ListView.builder(
              itemCount: _cars.length,
              itemBuilder: (context, index) {
                final car = _cars[index];
                return ListTile(
                  title: Text('${car['_id']}'),
                  subtitle: Text('${car['color']}'),
                );
              },
            ),
    );
  }
}
```

The observer watches local data. For remote updates, the app must also run sync and hold a sync subscription covering these cars. Keep the shared Ditto instance open until screen cleanup finishes.

