Flutter Web supports **bytes, not file paths**, for attachments. Use `file_picker` with `withData: true`, store the returned `Attachment` in an `ATTACHMENT` field, then fetch its token and render the bytes with `Image.memory`.

```dart
import 'dart:typed_data';
import 'package:ditto_live/ditto_live.dart';
import 'package:file_picker/file_picker.dart';
import 'package:flutter/material.dart';

Future<void> pickAndSavePhoto(Ditto ditto, String id) async {
  final picked = await FilePicker.platform.pickFiles(
    type: FileType.image,
    withData: true,
  );
  if (picked == null) return;

  final file = picked.files.single;
  final bytes = file.bytes;
  if (bytes == null) throw StateError('No image bytes returned');

  final attachment = await ditto.store.newAttachment(
    bytes,
    AttachmentMetadata({'name': file.name}), // Positional argument.
  );

  await ditto.store.execute(
    'INSERT INTO COLLECTION photos (image ATTACHMENT) '
    'DOCUMENTS (:doc) ON ID CONFLICT DO UPDATE',
    arguments: {
      'doc': {'_id': id, 'image': attachment},
    },
  );
}

Future<Uint8List> loadPhoto(Ditto ditto, String id) async {
  final result = await ditto.store.execute(
    'SELECT * FROM COLLECTION photos (image ATTACHMENT) '
    'WHERE _id = :id',
    arguments: {'id': id},
  );
  if (result.items.isEmpty) throw StateError('Photo not found');

  final token =
      result.items.first.value['image'] as Map<String, dynamic>;
  final fetcher = ditto.store.fetchAttachment(token, (_) {});
  final attachment = await fetcher.attachment;
  if (attachment == null) throw StateError('Photo unavailable');

  return await attachment.data;
}
```

