```dart
import 'package:ditto_live/ditto_live.dart';
import 'package:flutter/material.dart';

class NearbyPeersScreen extends StatefulWidget {
  const NearbyPeersScreen({super.key, required this.ditto});

  final Ditto ditto;

  @override
  State<NearbyPeersScreen> createState() => _NearbyPeersScreenState();
}

class _NearbyPeersScreenState extends State<NearbyPeersScreen> {
  late PresenceObserver _observer;
  PresenceGraph? _graph;

  @override
  void initState() {
    super.initState();
    _startWatching();
  }

  void _startWatching() {
    _graph = widget.ditto.presence.graph;
    _observer = widget.ditto.presence.observe((graph) {
      if (!mounted) return;
      setState(() => _graph = graph);
    });
  }

  @override
  void didUpdateWidget(covariant NearbyPeersScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (!identical(oldWidget.ditto, widget.ditto)) {
      _observer.stop();
      _startWatching();
    }
  }

  @override
  void dispose() {
    _observer.stop(); // Presence uses stop(), not cancel().
    super.dispose();
  }

  static String _label(ConnectionType type) => switch (type) {
        ConnectionType.bluetooth => 'Bluetooth',
        ConnectionType.accessPoint => 'LAN',
        ConnectionType.p2pWifi => 'Wi-Fi P2P',
        ConnectionType.webSocket => 'WebSocket',
        ConnectionType.multicast => 'Multicast',
      };

  String _connectionLabel(PresenceGraph graph, Peer peer) {
    final localKey = graph.localPeer.peerKey;

    // A peer's connections can include links to other remote peers.
    final labels = [
      ...graph.localPeer.connections,
      ...peer.connections,
    ]
        .where((c) =>
            (c.peer1 == localKey && c.peer2 == peer.peerKey) ||
            (c.peer2 == localKey && c.peer1 == peer.peerKey))
        .map((c) => _label(c.connectionType))
        .toSet()
        .toList()
      ..sort();

    return labels.isEmpty
        ? 'No direct connection'
        : labels.join(', ');
  }

  @override
  Widget build(BuildContext context) {
    final graph = _graph!;
    final peers = graph.remotePeers.toList()
      ..sort((a, b) {
        final byName = a.deviceName.compareTo(b.deviceName);
        return byName != 0 ? byName : a.peerKey.compareTo(b.peerKey);
      });

    return Scaffold(
      appBar: AppBar(title: const Text('Nearby peers')),
      body: peers.isEmpty
          ? const Center(child: Text('No peers found'))
          : ListView.builder(
              itemCount: peers.length,
              itemBuilder: (context, index) {
                final peer = peers[index];
                return ListTile(
                  key: ValueKey(peer.peerKey),
                  leading: const Icon(Icons.devices),
                  title: Text(
                    peer.deviceName.trim().isEmpty
                        ? 'Unnamed device'
                        : peer.deviceName,
                  ),
                  subtitle: Text(_connectionLabel(graph, peer)),
                );
              },
            ),
    );
  }
}
