The Ditto skills don't apply here, since you're not using Ditto. This is a plain Riverpod and Drift problem.

**Why the whole screen rebuilds:** Drift's `watch()` runs the query again after any write to the tables it reads, and emits a new `List`. Dart compares `List`s by identity, so every emission counts as a change. Every widget that watches that provider then rebuilds, including the whole `ListView`.

**Fix: the screen watches only the row IDs, and each row watches its own record.**

```dart
// 1. List of IDs only. Emits only when rows are added, removed or reordered.
final todoIdsProvider = StreamProvider<List<int>>((ref) {
  final db = ref.watch(dbProvider);
  final q = db.selectOnly(db.todos)
    ..addColumns([db.todos.id])
    ..orderBy([OrderingTerm.asc(db.todos.createdAt)]);
  return q
      .map((r) => r.read(db.todos.id)!)
      .watch()
      .distinct(const ListEquality<int>().equals); // package:collection
});

// 2. One provider per row. Drift data classes implement ==, so rows that
//    didn't change don't notify.
final todoProvider = StreamProvider.family<Todo, int>((ref, id) {
  final db = ref.watch(dbProvider);
  return (db.select(db.todos)..where((t) => t.id.equals(id)))
      .watchSingle()
      .distinct();
});

// 3. Screen
class TodoList extends ConsumerWidget {
  const TodoList({super.key});
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final ids = ref.watch(todoIdsProvider).valueOrNull ?? const [];
    return ListView.builder(
      itemCount: ids.length,
      itemExtent: 72, // if rows have a fixed height; makes scrolling cheaper
      itemBuilder: (_, i) => TodoTile(key: ValueKey(ids[i]), id: ids[i]),
    );
  }
}

class TodoTile extends ConsumerWidget {
  const TodoTile({super.key, required this.id});
  final int id;
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final todo = ref.watch(todoProvider(id)).valueOrNull;
    if (todo == null) return const SizedBox.shrink();
    return ListTile(title: Text(todo.title));
  }
}
```

**Other changes that help:**
- **`select` for single fields:** If a widget needs only one field, use `ref.watch(todoProvider(id).select((a) => a.valueOrNull?.title))`. It then rebuilds only when that field changes.
- **Fewer tables in the query:** Any write to any table in the query triggers a new run, so leave out joins you don't need. For `customSelect`, set `readsFrom:` accurately.
- **Batch your writes:** Put bulk updates in `db.transaction` or `db.batch`. You get one emission instead of one per row.
- **Keep work out of `build`:** Do sorting, mapping and formatting inside the provider, using `.map` on the stream, not in `build`. Use `const` child widgets where you can.
- **Avoid restarting queries:** If you use `autoDispose` on the row family, rows that scroll off-screen and back restart their queries. Add `ref.keepAlive()` or a short cache timer if that shows up as a cost.
- **Simpler alternative:** You can keep one full-list provider and just add `.distinct(const ListEquality<Todo>().equals)`. That stops emissions when nothing actually changed, but a real change to one row still rebuilds the whole list. The per-row family is what stops that.

Check the result with Flutter DevTools' "Track widget rebuilds": after one row update, only that row's `TodoTile` should rebuild.

Here's the screen, written for `ditto_live` 5.2.0. It takes your already-open `Ditto` instance. It doesn't open or close Ditto itself, because Ditto should stay open for the whole app, not one screen.

```dart
// lib/nearby_peers_screen.dart
import 'package:ditto_live/ditto_live.dart';
import 'package:flutter/material.dart';

/// Lists remote peers with their device name and transports, live.
class NearbyPeersScreen extends StatefulWidget {
  const NearbyPeersScreen({super.key, required this.ditto});

  final Ditto ditto;

  @override
  State<NearbyPeersScreen> createState() => _NearbyPeersScreenState();
}

/// Plain snapshot of one peer, so the UI never holds SDK objects.
class _PeerRow {
  const _PeerRow({
    required this.peerKey,
    required this.deviceName,
    required this.os,
    required this.directTransports,
    required this.isConnectedToDittoServer,
  });

  final String peerKey;
  final String deviceName;
  final String os;

  /// Empty when the peer is reached only through other peers (multihop).
  final Set<ConnectionType> directTransports;
  final bool isConnectedToDittoServer;
}

class _NearbyPeersScreenState extends State<NearbyPeersScreen> {
  PresenceObserver? _observer;
  List<_PeerRow> _peers = const [];

  @override
  void initState() {
    super.initState();
    // Called once soon after observe() with the current graph, then whenever
    // peers or connections change. It runs on this (UI) isolate.
    _observer = widget.ditto.presence.observe(_onGraph);
  }

  void _onGraph(PresenceGraph graph) {
    if (!mounted) return;
    final localKey = graph.localPeer.peerKey;

    final rows = graph.remotePeers.map((peer) {
      // A peer's connections can include links between other remote peers.
      // Keep only the links to this device.
      final direct = peer.connections
          .where((c) => c.peer1 == localKey || c.peer2 == localKey)
          .map((c) => c.connectionType)
          .toSet();
      return _PeerRow(
        peerKey: peer.peerKey,
        deviceName: peer.deviceName,
        os: peer.os.toString(),
        directTransports: direct,
        isConnectedToDittoServer: peer.isConnectedToDittoServer,
      );
    }).toList()
      ..sort((a, b) => a.deviceName.compareTo(b.deviceName));

    setState(() => _peers = rows);
  }

  @override
  void dispose() {
    // Dropping the reference does NOT stop it; stop() is required.
    _observer?.stop();
    _observer = null;
    super.dispose();
  }

  static String _label(ConnectionType type) => switch (type) {
        ConnectionType.bluetooth => 'Bluetooth',
        ConnectionType.accessPoint => 'LAN',
        ConnectionType.p2pWifi => 'Wi-Fi P2P',
        ConnectionType.webSocket => 'WebSocket',
        ConnectionType.multicast => 'Multicast', // 5.1.0+
      };

  static IconData _icon(ConnectionType type) => switch (type) {
        ConnectionType.bluetooth => Icons.bluetooth,
        ConnectionType.accessPoint => Icons.lan,
        ConnectionType.p2pWifi => Icons.wifi_tethering,
        ConnectionType.webSocket => Icons.cloud,
        ConnectionType.multicast => Icons.cell_tower,
      };

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Nearby peers (${_peers.length})')),
      body: _peers.isEmpty
          ? const Center(child: Text('No peers nearby'))
          : ListView.separated(
              itemCount: _peers.length,
              separatorBuilder: (_, __) => const Divider(height: 1),
              itemBuilder: (context, i) {
                final p = _peers[i];
                final name = p.deviceName.isEmpty ? p.peerKey : p.deviceName;
                return ListTile(
                  key: ValueKey(p.peerKey),
                  leading: const Icon(Icons.devices),
                  title: Text(name),
                  subtitle: Padding(
                    padding: const EdgeInsets.only(top: 4),
                    child: Wrap(
                      spacing: 6,
                      runSpacing: 4,
                      children: [
                        if (p.directTransports.isEmpty)
                          const Chip(
                            avatar: Icon(Icons.alt_route, size: 16),
                            label: Text('Via other peers'),
                            visualDensity: VisualDensity.compact,
                          ),
                        for (final t in p.directTransports)
                          Chip(
                            avatar: Icon(_icon(t), size: 16),
                            label: Text(_label(t)),
                            visualDensity: VisualDensity.compact,
                          ),
                        if (p.isConnectedToDittoServer)
                          const Chip(
                            avatar: Icon(Icons.cloud_done, size: 16),
                            label: Text('Server'),
                            visualDensity: VisualDensity.compact,
                          ),
                      ],
                    ),
                  ),
                  trailing: Text(p.os, style: Theme.of(context).textTheme.bodySmall),
                );
              },
            ),
    );
  }
}
```

