import 'package:ditto_live/ditto_live.dart';
import 'package:flutter/widgets.dart';
import 'package:permission_handler/permission_handler.dart';

late final Ditto ditto;
late final SyncSubscription tasksSubscription;

const runtimePermissions = <String, Permission>{
  'android.permission.BLUETOOTH_SCAN': Permission.bluetoothScan,
  'android.permission.BLUETOOTH_CONNECT': Permission.bluetoothConnect,
  'android.permission.BLUETOOTH_ADVERTISE': Permission.bluetoothAdvertise,
  'android.permission.NEARBY_WIFI_DEVICES': Permission.nearbyWifiDevices,
  'android.permission.ACCESS_FINE_LOCATION': Permission.locationWhenInUse,
  'android.permission.ACCESS_COARSE_LOCATION': Permission.locationWhenInUse,
};

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();

  const license = String.fromEnvironment('DITTO_LICENSE');
  if (license.isEmpty) {
    throw StateError('Supply your offline license through DITTO_LICENSE');
  }

  await Ditto.init();
  ditto = await Ditto.open(
    const DittoConfig(
      databaseID: 'YOUR_DATABASE_ID',
      connect: DittoConfigConnectSmallPeersOnly(),
    ),
  );

  try {
    ditto.setOfflineOnlyLicenseToken(license);

    // Empty on iOS; Android needs runtime grants before starting sync.
    final permissions = DittoSyncPermissions();
    final missing = await permissions.missingPermissions();
    final requests = missing
        .map((name) => runtimePermissions[name])
        .nonNulls
        .toSet()
        .toList();
    if (requests.isNotEmpty) await requests.request();
    if ((await permissions.missingPermissions()).isNotEmpty) {
      throw StateError('Nearby sync permissions were not granted');
    }

    ditto.sync.start(); // Synchronous; native P2P is enabled by default.
    tasksSubscription =
        ditto.sync.registerSubscription('SELECT * FROM tasks');

    await ditto.store.execute(
      'INSERT INTO tasks DOCUMENTS (:task) ON ID CONFLICT DO UPDATE',
      arguments: {
        'task': {
          '_id': 'first-task',
          'title': 'Try Ditto',
        },
      },
    );

    final result = await ditto.store.execute('SELECT title FROM tasks');
    final List<String> titles = result.items
        .map((item) => item.value['title'] as String)
        .toList();

    runApp(
      Directionality(
        textDirection: TextDirection.ltr,
        child: Center(child: Text(titles.join('\n'))),
      ),
    );
  } catch (_) {
    await ditto.close();
    rethrow;
  }
}
```

The first query returns `['Try Ditto']` in a fresh store. The subscription enables receiving matching tasks from peers; the query reads the current local store.

