Pass your existing, open Ditto instance with sync started and native permissions granted. Presence reports known mesh peers, which may include indirect or disconnected peers; it does not measure physical proximity.

```dart
import 'package:ditto_live/ditto_live.dart';
import 'package:flutter/material.dart';

class NearbyPeersScreen extends StatefulWidget {
  const NearbyPeersScreen({super.key, required this.ditto});

  final Ditto ditto;

  @override
  State<NearbyPeersScreen> createState() => _NearbyPeersScreenState();
}

class _NearbyPeersScreenState extends State<NearbyPeersScreen> {
  late PresenceGraph _graph;
  PresenceObserver? _observer;

  @override
  void initState() {
    super.initState();
    _watch();
  }

  void _watch() {
    _graph = widget.ditto.presence.graph;
    _observer = widget.ditto.presence.observe((graph) {
      if (!mounted) return;
      setState(() => _graph = graph);
    });
  }

  @override
  void didUpdateWidget(covariant NearbyPeersScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (!identical(oldWidget.ditto, widget.ditto)) {
      _observer?.stop();
      _watch();
    }
  }

  @override
  void dispose() {
    _observer?.stop();
    super.dispose();
  }

  String _connectionLabel(Peer peer) {
    final localKey = _graph.localPeer.peerKey;
    final labels = peer.connections
        .where((c) =>
            (c.peer1 == localKey && c.peer2 == peer.peerKey) ||
            (c.peer2 == localKey && c.peer1 == peer.peerKey))
        .map((c) => switch (c.connectionType) {
              ConnectionType.bluetooth => 'Bluetooth',
              ConnectionType.accessPoint => 'LAN',
              ConnectionType.p2pWifi => 'Wi-Fi P2P',
              ConnectionType.webSocket => 'WebSocket',
              ConnectionType.multicast => 'Multicast',
            })
        .toSet()
        .toList()
      ..sort();

    return labels.isEmpty
        ? 'No direct connection'
        : labels.join(', ');
  }

  @override
  Widget build(BuildContext context) {
    final peers = _graph.remotePeers.toList()
      ..sort((a, b) {
        final byName = a.deviceName.compareTo(b.deviceName);
        return byName != 0 ? byName : a.peerKey.compareTo(b.peerKey);
      });

    return Scaffold(
      appBar: AppBar(title: const Text('Nearby peers')),
      body: peers.isEmpty
          ? const Center(child: Text('No peers found'))
          : ListView.builder(
              itemCount: peers.length,
              itemBuilder: (context, index) {
                final peer = peers[index];
                return ListTile(
                  leading: const Icon(Icons.devices),
                  title: Text(
                    peer.deviceName.trim().isEmpty
                        ? 'Unnamed device'
                        : peer.deviceName,
                  ),
                  subtitle: Text(_connectionLabel(peer)),
                );
              },
            ),
    );
  }
}
```

`observe()` updates on peer and connection changes. `stop()` releases the observer when the screen is disposed; the shared Ditto instance stays open.

Using the local `flutter-sdk` guidance: attach one `changes` listener, copy results into a list, and cancel both the listener and observer.

```dart
import 'dart:async';

import 'package:ditto_live/ditto_live.dart';
import 'package:flutter/material.dart';

class CarsScreen extends StatefulWidget {
  const CarsScreen({
    super.key,
    required this.ditto,
    required this.color,
  });

  final Ditto ditto;
  final String color;

  @override
  State<CarsScreen> createState() => _CarsScreenState();
}

class _CarsScreenState extends State<CarsScreen> {
  late StoreObserver _observer;
  late StreamSubscription<QueryResult> _changes;
  List<Map<String, dynamic>> _cars = [];
  Object? _error;

  @override
  void initState() {
    super.initState();
    _observe();
  }

  void _observe() {
    _cars = [];
    _error = null;

    final observer = widget.ditto.store.registerObserver(
      'SELECT * FROM cars WHERE color = :color',
      arguments: {'color': widget.color},
    );
    _observer = observer;

    // Listen immediately; do not also supply onChange.
    _changes = observer.changes.listen(
      (result) {
        if (!mounted || !identical(_observer, observer)) return;
        final cars = result.items.map((item) => item.value).toList();
        setState(() {
          _cars = cars;
          _error = null;
        });
      },
      onError: (Object error) {
        if (!mounted || !identical(_observer, observer)) return;
        setState(() => _error = error);
      },
    );
  }

  void _stopObserving() {
    unawaited(_changes.cancel());
    _observer.cancel();
  }

  @override
  void didUpdateWidget(covariant CarsScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.color != widget.color ||
        !identical(oldWidget.ditto, widget.ditto)) {
      _stopObserving();
      _observe();
    }
  }

  @override
  void dispose() {
    _stopObserving();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('${widget.color} cars')),
      body: _error != null
          ? Center(child: Text('Unable to load cars: $_error'))
          : _cars.isEmpty
              ? const Center(child: Text('No matching cars'))
              : ListView.builder(
                  itemCount: _cars.length,
                  itemBuilder: (context, index) {
                    final car = _cars[index];
                    return ListTile(
                      title: Text('${car['_id']}'),
                      subtitle: Text('${car['color']}'),
                    );
                  },
                ),
    );
  }
}
```

This observes local data, including incoming synced changes. The app should own any required sync subscription and keep Ditto open; the screen never closes the shared instance.

